  handleMCQ(val, ind) {
    debugger
    for (let i = 0; i < this.queslist.value.length; i++) {
      if (this.queslist.value[i].quesString == "SubQues" + ind) {
        if (this.queslist.length == i) {
          this.queslist.removeAt(i - 1)
        }
        else {
          this.queslist.removeAt(i)
        }
      }
    }

    this.queslist.value.map((mp, index) => {
      if (mp.quesString == "SubQues" + ind) {
        this.queslist.removeAt(index)
      }
    })

    console.log("pslice", this.queslist)
    if (this.form_data.value[ind] && this.form_data.value[ind].sub) {
      for (var i = 0; i < this.form_data.value[ind].sub.length; i++) {
        for (var j = 0; j < this.form_data.value[ind].sub[i].show_child.length; j++) {
          if (val.detail.value == this.form_data.value[ind].sub[i].show_child[j]) {
            var subques = this.form_data.value[ind].sub[i]
            this.queslist.push(this.fb.group({
              id: new FormControl(subques.id, null),
              question_desc: new FormControl(subques.question_desc, null),
              question_desc_t: new FormControl(subques.question_desc_t, null),
              question_text: new FormControl(subques.question_text, null),
              question_text_t: new FormControl(subques.question_text_t, null),
              question_title: new FormControl(subques.question_title, null),
              question_title_t: new FormControl(subques.question_title_t, null),
              question_type: new FormControl(subques.question_type, null),
              required: new FormControl(subques.required, null),
              verify: new FormControl(subques.verify, null),
              options: new FormControl(subques.options, null),
              parent_form_controller: new FormControl(subques[i].parent_form_controller, null),
              form_controller: new FormControl(subques.form_controller, null),
            dis_form_controller: new FormControl(subques[i].dis_form_controller, null),
              [subques.form_controller]: new FormControl('', Validators.compose([Validators.required])),
              sub: new FormControl(subques.sub, null),
              quesString: 'SubQues' + ind,
              IsPhoto:false,
            }));
          }
        }
      }
    }

  }

